// Comprehensive Activities Database with external links and country availability

import { colleges, College } from "./colleges";

export interface Activity {
  id: string;
  name: string;
  category: string;
  type: "Competition" | "Project" | "Research" | "Leadership" | "Service";
  cost: "Free" | "Paid" | "Scholarships Available";
  difficulty: "Beginner" | "Intermediate" | "Advanced";
  gradeSuitability: string;
  description: string;
  detailedDescription: string;
  relevantMajors: string[];
  whyRelevant: string;
  countries: string[]; // Empty array means global/online
  learnMoreUrl: string;
  applyUrl: string | null;
  deadline?: string;
  priorityFactors: {
    majorAlignment: number; // 1-10
    collegeImpact: number; // 1-10
    uniqueness: number; // 1-10
  };
}

// Helper to determine if activity is available in country
export const isActivityAvailableInCountry = (activity: Activity, country: string): boolean => {
  if (activity.countries.length === 0) return true; // Global/online
  return activity.countries.includes(country);
};

// Get college level from name
const getCollegeLevelFromName = (collegeName: string): "regional" | "national" | "global" => {
  const college = colleges.find(c => c.name === collegeName);
  return college?.level || "national";
};

// Get college strong majors
const getCollegeStrongMajors = (collegeName: string): string[] => {
  const college = colleges.find(c => c.name === collegeName);
  return college?.strongMajors || [];
};

// Raw scoring used internally for ranking
const computePriorityScore = (
  activity: Activity,
  userMajor: string,
  targetCollegeName?: string
): number => {
  const majorMatch = activity.relevantMajors.includes(userMajor);
  const { majorAlignment, collegeImpact, uniqueness } = activity.priorityFactors;
  const targetCollegeLevel = targetCollegeName ? getCollegeLevelFromName(targetCollegeName) : "national";
  const collegeStrongMajors = targetCollegeName ? getCollegeStrongMajors(targetCollegeName) : [];
  const collegeAligned = activity.relevantMajors.some(m => collegeStrongMajors.includes(m));

  let score = 0;
  score += majorMatch ? majorAlignment * 1.5 : majorAlignment * 0.3;
  if (collegeAligned) score += 3;
  if (targetCollegeLevel === "global") score += collegeImpact * 1.2;
  else if (targetCollegeLevel === "national") score += collegeImpact * 0.8;
  else score += collegeImpact * 0.5;
  score += uniqueness * 0.5;
  return score;
};

// Cache for the rank-based priority map per (major|college) key
const priorityMapCache = new Map<string, Map<string, "High" | "Medium" | "Low">>();

const buildPriorityMap = (
  userMajor: string,
  targetCollegeName?: string
): Map<string, "High" | "Medium" | "Low"> => {
  const key = `${userMajor}||${targetCollegeName || ""}`;
  const cached = priorityMapCache.get(key);
  if (cached) return cached;

  // Score every activity that's relevant to this major
  const scored = activities
    .map(a => ({ id: a.id, score: computePriorityScore(a, userMajor, targetCollegeName), majorMatch: a.relevantMajors.includes(userMajor) }))
    .sort((a, b) => b.score - a.score);

  const map = new Map<string, "High" | "Medium" | "Low">();
  const total = scored.length;

  // Targets: at least 5 High, at least 4 Medium, at least 2 Low (per major view)
  // Use proportional split with floors so distribution is always meaningful.
  const highCount = Math.max(5, Math.round(total * 0.28));
  const lowCount = Math.max(2, Math.round(total * 0.32));
  const highCutoff = Math.min(highCount, Math.max(0, total - lowCount - 4));
  const lowStart = Math.max(highCutoff + 4, total - lowCount);

  scored.forEach((item, idx) => {
    let bucket: "High" | "Medium" | "Low";
    if (idx < highCutoff) bucket = "High";
    else if (idx >= lowStart) bucket = "Low";
    else bucket = "Medium";
    map.set(item.id, bucket);
  });

  priorityMapCache.set(key, map);
  return map;
};

// Calculate priority based on user's major AND target college (rank-based, guarantees mix)
export const calculatePriority = (
  activity: Activity,
  userMajor: string,
  targetCollegeName?: string
): "High" | "Medium" | "Low" => {
  if (!userMajor) return "Medium";
  const map = buildPriorityMap(userMajor, targetCollegeName);
  return map.get(activity.id) || "Medium";
};

// Generate priority explanation based on user's goals
export const generatePriorityExplanation = (
  activity: Activity,
  priority: "High" | "Medium" | "Low",
  userMajor: string,
  targetCollegeName?: string
): string => {
  const majorMatch = activity.relevantMajors.includes(userMajor);
  const collegeLevel = targetCollegeName ? getCollegeLevelFromName(targetCollegeName) : null;
  const collegeStrongMajors = targetCollegeName ? getCollegeStrongMajors(targetCollegeName) : [];
  const collegeAligned = activity.relevantMajors.some(m => collegeStrongMajors.includes(m));
  
  if (priority === "High") {
    if (majorMatch && collegeAligned && targetCollegeName) {
      return `Highly recommended because it directly aligns with ${userMajor} and is valued by ${targetCollegeName}, which is known for programs in ${collegeStrongMajors.slice(0, 2).join(" and ")}.`;
    }
    if (majorMatch) {
      return `Strongly recommended because it directly develops skills essential for ${userMajor} and demonstrates initiative that top programs look for.`;
    }
    return `Highly valued by competitive colleges as it demonstrates exceptional achievement and initiative.`;
  }
  
  if (priority === "Medium") {
    if (majorMatch) {
      return `Good fit for ${userMajor} students. While not essential, it provides valuable experience and differentiates your application.`;
    }
    if (collegeAligned && targetCollegeName) {
      return `This activity aligns with ${targetCollegeName}'s values and can strengthen your overall profile even though it's not directly related to ${userMajor}.`;
    }
    return `Provides solid extracurricular development and can complement your core activities.`;
  }
  
  // Low priority
  if (activity.relevantMajors.some(m => collegeStrongMajors.includes(m))) {
    return `Less directly relevant to ${userMajor}, but may still add value if you have capacity and genuine interest.`;
  }
  return `Consider this activity only if you have extra capacity after focusing on higher-priority activities aligned with your goals.`;
};

