// Get activities by major
export const getActivitiesByMajor = (major: string): Activity[] => {
  return activities.filter(a => a.relevantMajors.includes(major));
};

// Get activities by country
export const getActivitiesByCountry = (country: string): Activity[] => {
  return activities.filter(a => isActivityAvailableInCountry(a, country));
};

// Get activity types
export const getActivityTypes = (): Activity["type"][] => {
  return ["Competition", "Project", "Research", "Leadership", "Service"];
};

// Get activity categories
export const getActivityCategories = (): string[] => {
  const categories = new Set(activities.map(a => a.category));
  return Array.from(categories).sort();
};

// Activities to avoid - low-impact or overused activities
export const avoidActivities = [
  {
    name: "Generic NHS Membership",
    reason: "Simply being a member without leadership or meaningful projects doesn't differentiate you. Millions of students have NHS on their applications."
  },
  {
    name: "Hospital Volunteering (Without Depth)",
    reason: "Common among pre-med applicants. Unless you have significant hours, leadership, or a specific project, it blends in."
  },
  {
    name: "Mission Trips (Short-Term)",
    reason: "One-week trips can appear performative. Long-term sustained engagement is more impactful."
  },
  {
    name: "Generic Club Memberships",
    reason: "Being 'a member' of 10 clubs is less impressive than leadership or impact in 2-3 activities."
  },
  {
    name: "Unpaid Family Business Work",
    reason: "Can appear as resume padding unless you can demonstrate real responsibility and learning."
  },
  {
    name: "Pay-to-Play Summer Programs",
    reason: "Expensive summer programs at universities are often seen as purchased experiences rather than earned achievements."
  }
];
